import os,threading,subprocess,pathlib,json,time
childbox={};ready=threading.Event();release=threading.Event()
def spawn():
 c=subprocess.Popen(['/bin/sleep','3']);childbox.update(pid=c.pid,creatorTid=threading.get_native_id());ready.set()
 try:release.wait(2)
 finally:c.wait(timeout=5)
t=threading.Thread(target=spawn);t.start();assert ready.wait(2)
root=pathlib.Path('/proc')/str(os.getpid())/'task'
results={p.name:(p/'children').read_text().strip() for p in root.iterdir()}
answer={'mainPid':os.getpid(),'child':childbox,'taskChildren':results,'source':'Actual Linux CPU host probe: one owned /bin/sleep spawned by a non-main Python thread. No Java/workload/OS tuning.'}
release.set();t.join(timeout=6);assert not t.is_alive();print(json.dumps(answer))
